AHB.audio({"groups": {"part-01-vocabulary": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-01-vocabulary/001.mp3", "text": "Lina writes a (1)… for NorthBridge."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-01-vocabulary/002.mp3", "text": "The unit (2)… is 50 dollars per tonne."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-01-vocabulary/003.mp3", "text": "For a big order, she gives a 10% (3)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-01-vocabulary/004.mp3", "text": "The (4)… is 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-01-vocabulary/005.mp3", "text": "The (5)… is dollars, and the price is (6)… for 30 days."}], "title": "Read and listen"}], "part-02-grammar": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/001.mp3", "text": "BIG NUMBERS: 100 = a hundred, 1,000 = a thousand, 1,000,000 = a million. 45,000 = forty-five thousand."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/002.mp3", "text": "To SAY A PRICE: $50 = fifty dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/003.mp3", "text": "We say the unit after: 45 dollars PER TONNE, per bag, or each."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/004.mp3", "text": "Question: How much is it?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/005.mp3", "text": "Answer: It's 45 dollars per tonne."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/006.mp3", "text": "COMPARATIVES compare two things."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/007.mp3", "text": "For short adjectives, add -er: cheap → cheaper, high → higher, low → lower, big → bigger."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/008.mp3", "text": "For long adjectives (two syllables or more), use more: expensive → more expensive, difficult → more difficult."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/009.mp3", "text": "Some are irregular: good → better, bad → worse."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/010.mp3", "text": "We use THAN to compare: Cement is cheaper than steel."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/011.mp3", "text": "Steel is more expensive than iron."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/012.mp3", "text": "QUANTIFIERS say how much or how many."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/013.mp3", "text": "A LOT OF (much/many) for a big amount: a lot of cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/014.mp3", "text": "A LITTLE for a small amount (uncountable): a little water."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/015.mp3", "text": "A FEW for a small number (countable): a few boxes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/016.mp3", "text": "MORE (+) and LESS / FEWER (−): We can give you a better price for more tonnes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/017.mp3", "text": "To find the TOTAL, multiply: unit price × quantity. $45 × 1,000 tonnes = $45,000."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/018.mp3", "text": "For comparatives, use -er OR more, not both: 'cheaper' (NOT 'more cheaper'), 'more expensive' (NOT 'expensiver')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-02-grammar/019.mp3", "text": "And always say the currency: '45 dollars' (NOT just '45')."}], "title": "Read and listen"}], "part-03-listening": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/001.mp3", "text": "Listen and read. (Your teacher will read the dialogue, or play the audio.)"}], "title": "Read and listen"}, {"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/002.mp3", "text": "Thank you for the catalogue. Now, how much is the cement, per tonne?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/003.mp3", "text": "The unit price is 50 dollars per tonne."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/004.mp3", "text": "And I want 1,000 tonnes. So the total is 50,000 dollars?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/005.mp3", "text": "Yes. But for a big order, we can give you a discount. 10% off."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/006.mp3", "text": "10%? That's very good. So what is the new price?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/007.mp3", "text": "With the discount, it's 45 dollars per tonne. The total is 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/008.mp3", "text": "Excellent. And is that in dollars?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/009.mp3", "text": "Yes, in US dollars. And the price is valid for 30 days."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/010.mp3", "text": "Perfect. Your price is cheaper than the other companies, and the quality is higher. Thank you, Lina."}], "title": "Dialogue D1"}, {"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/011.mp3", "text": "Can you give me a discount?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/012.mp3", "text": "Yes, of course. For a big order, we give 10% off."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/013.mp3", "text": "And for a very big order? 5,000 tonnes?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/014.mp3", "text": "For 5,000 tonnes, we can give 15% off."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/015.mp3", "text": "So the price is lower for more tonnes?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-04/part-03-listening/016.mp3", "text": "Yes. A bigger order, a bigger discount. That's a better price for you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-03-listening/017.mp3", "text": "Great. Let me think about the quantity. Thank you, Lina."}], "title": "Dialogue D2"}], "part-04-speaking": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-04-speaking/001.mp3", "text": "A: Ask the price ('How much is the cement, per tonne?')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-04-speaking/002.mp3", "text": "B: Give the unit price ('It's 50 dollars per tonne')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-04-speaking/003.mp3", "text": "A: Ask for a discount ('Can you give a discount?')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-04-speaking/004.mp3", "text": "B: Give a discount ('For a big order, 10% off')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-04-speaking/005.mp3", "text": "A: Work out the total ('So the total is…')."}], "title": "Read and listen"}], "part-05-reading": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/001.mp3", "text": "A price looks like a simple thing — just a number."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/002.mp3", "text": "But a price is one of the most important decisions a company makes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/003.mp3", "text": "Set the price too high, and the partner buys from another company."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/004.mp3", "text": "Set it too low, and you sell a lot but make no profit."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/005.mp3", "text": "The right price is not the highest, and not the lowest."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/006.mp3", "text": "It is a FAIR price — good for the buyer, and good for the seller."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/007.mp3", "text": "How does a company find a fair price?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/008.mp3", "text": "It thinks about three things."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/009.mp3", "text": "First, its COSTS: the money it spends to make the product."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/010.mp3", "text": "The price must be higher than the cost, or there is no profit."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/011.mp3", "text": "Second, the COMPETITION: the prices of other companies."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/012.mp3", "text": "If your cement is 50 dollars and another company's cement is 45, you can lose the sale."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/013.mp3", "text": "But you win the sale if your quality is higher."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/014.mp3", "text": "Third, the CUSTOMER: what the partner can pay, and how much they buy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/015.mp3", "text": "For a big order, a small discount is fair, because the company still makes money on the large quantity."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/016.mp3", "text": "This is why a discount is not just 'being nice'."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/017.mp3", "text": "A discount is a clever tool."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/018.mp3", "text": "'A bigger order, a bigger discount' helps both sides: the partner pays less per tonne, and the company sells more tonnes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/019.mp3", "text": "Both are happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/020.mp3", "text": "This is the heart of good business: both sides get a fair deal."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/021.mp3", "text": "One side does not win, and one side does not lose."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/022.mp3", "text": "A fair price today makes a partner who comes back tomorrow."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/023.mp3", "text": "And here is the deeper truth: partners do not just buy a price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/024.mp3", "text": "They buy trust."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/025.mp3", "text": "When Ms. Chen reads a clear, fair quotation, she thinks, 'This company is honest."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/026.mp3", "text": "They are not trying to trick me.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/027.mp3", "text": "A high, unclear price makes a partner nervous."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/028.mp3", "text": "A fair, clear price makes a partner relax."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/029.mp3", "text": "So when you write a price, remember: you do not just write a number."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/030.mp3", "text": "You tell the partner what kind of company you are."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/031.mp3", "text": "Write a fair, clear price — and you write the first line of a long partnership."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/032.mp3", "text": "A price is an important (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/033.mp3", "text": "The right price is (2)… — good for both sides."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/034.mp3", "text": "A company thinks about its (3)…, the competition, and the customer."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/035.mp3", "text": "A (4)… helps both sides: the partner pays less, the company sells more."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/036.mp3", "text": "And a fair price builds (5)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-05-reading/037.mp3", "text": "When you write a price, you tell the partner what (6)… of company you are."}], "title": "Read and listen"}], "part-06-writing": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-06-writing/001.mp3", "text": "Sentence starters: “Please find our quotation below.” · “The price is … per tonne.” · “For … tonnes, the total is …” · “This price is valid for … days.”"}], "title": "Read and listen"}], "part-07-trade-skills": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/001.mp3", "text": "A quotation is a document, and a good one has clear parts."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/002.mp3", "text": "At the top: the PRODUCT (what it is)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/003.mp3", "text": "Then the UNIT PRICE (per tonne, per bag)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/004.mp3", "text": "Then the QUANTITY (how many)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/005.mp3", "text": "Then any DISCOUNT."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/006.mp3", "text": "Then the TOTAL (the final number)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/007.mp3", "text": "And finally, VALID UNTIL (how long the price is good)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/008.mp3", "text": "Every part is important."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/009.mp3", "text": "But two parts need special care."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/010.mp3", "text": "First, the CURRENCY: always write the currency — 45 DOLLARS, not just '45'."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/011.mp3", "text": "A partner in another country uses a different currency, so '45' alone is not clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/012.mp3", "text": "Second, the MATHS: check your total."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/013.mp3", "text": "If the unit price is 45 and the quantity is 1,000, the total is 45,000 — not 45,000,000 or 4,500."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/014.mp3", "text": "One wrong number in a quotation can cost a lot of money, or lose a partner's trust."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/015.mp3", "text": "So always check the numbers twice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/016.mp3", "text": "A quotation with the right currency and the right maths says: 'This company is careful and professional.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-07-trade-skills/017.mp3", "text": "That is exactly what a partner wants to see."}], "title": "Read and listen"}], "part-08-consolidation": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/001.mp3", "text": "Ms. Chen has two quotations on her desk."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/002.mp3", "text": "One is from Al-Hasan: cement at 45 dollars per tonne, high quality, valid for 30 days."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/003.mp3", "text": "The other is from a different company: cement at 52 dollars per tonne, lower quality."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/004.mp3", "text": "She compares them carefully."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/005.mp3", "text": "“Al-Hasan's cement is cheaper,” she thinks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/006.mp3", "text": "“45 dollars is less than 52 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/007.mp3", "text": "And Al-Hasan's cement is higher quality."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/008.mp3", "text": "So Al-Hasan is cheaper AND better."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/009.mp3", "text": "That is the best value.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/010.mp3", "text": "It is an easy decision."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/011.mp3", "text": "A lower price and a higher quality — you cannot ask for more."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/012.mp3", "text": "Ms. Chen writes to Lina: “Thank you for your quotation."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/013.mp3", "text": "I compared it with another company."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/014.mp3", "text": "Your price is cheaper, and your quality is higher."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/015.mp3", "text": "I would like to place an order for 1,000 tonnes.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/016.mp3", "text": "Lina is very happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/017.mp3", "text": "“We won the business,” she tells Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/018.mp3", "text": "“We were cheaper, yes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/019.mp3", "text": "But we did not win only because of the low price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/020.mp3", "text": "We won because we gave a fair price AND high quality."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/021.mp3", "text": "Together, that is value."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/022.mp3", "text": "A cheap, bad product is not a good deal."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/023.mp3", "text": "A fair price and a good product — that is what wins a partner.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-08-consolidation/024.mp3", "text": "And so, the quotation becomes an order — the biggest step yet."}], "title": "Read and listen"}], "part-09-cases": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/001.mp3", "text": "A colleague writes a quotation: 'Cement: 45 per tonne."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/002.mp3", "text": "Total: 45,000.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/003.mp3", "text": "But there is no currency."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/004.mp3", "text": "The partner does not know: dollars? euros? pounds?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/005.mp3", "text": "Write one clear price line, with the currency."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/006.mp3", "text": "The unit price is 45 dollars, and the quantity is 1,000 tonnes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/007.mp3", "text": "But the quotation says the total is 4,500 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/008.mp3", "text": "Another company offers cement at 40 dollars — cheaper than Al-Hasan's 45."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-09-cases/009.mp3", "text": "But their cement is low quality, and it is not always available."}], "title": "Read and listen"}], "part-10-review": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/001.mp3", "text": "The unit price of cement is 50 dollars per tonne."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/002.mp3", "text": "For a big order, we give a 10% discount, so the price is 45 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/003.mp3", "text": "For 1,000 tonnes, the total is 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/004.mp3", "text": "The price is valid for 30 days."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/005.mp3", "text": "Our cement is cheaper than the others."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/006.mp3", "text": "[Teacher reads] 'The unit price is 50 dollars per tonne."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/007.mp3", "text": "For a big order, we give 10% off, so it's 45 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/008.mp3", "text": "For 1,000 tonnes, the total is 45,000 dollars in US dollars.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/009.mp3", "text": "I can say prices, big numbers and money."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-10-review/010.mp3", "text": "I can compare offers (cheaper, more expensive)."}], "title": "Read and listen"}], "part-11-foundations": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/001.mp3", "text": "This unit is about prices."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/002.mp3", "text": "But hidden inside it is one of the most important ideas in all of business: the difference between PRICE and VALUE."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/003.mp3", "text": "Price is what you pay."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/004.mp3", "text": "Value is what you get."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/005.mp3", "text": "They are not the same thing — and understanding the difference will make you wiser in business and in life."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/006.mp3", "text": "Think about two products."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/007.mp3", "text": "One is cheap but bad: it breaks in a week, and you must buy another."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/008.mp3", "text": "The other costs a little more, but it is good, and it lasts for years."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/009.mp3", "text": "Which one is really cheaper?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/010.mp3", "text": "The first one looks cheaper — its price is lower."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/011.mp3", "text": "But you buy it again and again, so in the end you pay more."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/012.mp3", "text": "Its value is low."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/013.mp3", "text": "The second one has a higher price, but a higher value — and it is the better deal."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/014.mp3", "text": "The lesson: the lowest price is not always the cheapest, and the cheapest is not always the best value."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/015.mp3", "text": "This is why the best companies do not try to have the lowest price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/016.mp3", "text": "They try to give the best value: a fair price for a good product."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/017.mp3", "text": "And this is why the best partners do not look only at the price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/018.mp3", "text": "They ask, 'What do I really get for my money?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/019.mp3", "text": "Good quality?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/020.mp3", "text": "Can I trust them?'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/021.mp3", "text": "A wise buyer buys value, not just price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/022.mp3", "text": "And a wise seller sells value, not just a low number."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/023.mp3", "text": "So as you work in international trade, remember this simple, powerful idea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/024.mp3", "text": "Do not be the cheapest — be the best value."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/025.mp3", "text": "Give a fair price and a good product, on time, with honesty."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/026.mp3", "text": "Then your partners will pay a fair price gladly, and come back again and again, for years."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/027.mp3", "text": "Because in the end, people do not remember the exact price they paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/028.mp3", "text": "They remember if it was worth it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/029.mp3", "text": "Give them value, and they will remember you — and that is worth more than any discount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/030.mp3", "text": "Think of something you bought."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/031.mp3", "text": "Was it good value?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/032.mp3", "text": "Did you pay a low price but get a bad product, or a fair price and a good product?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/033.mp3", "text": "Tell your partner, and explain why."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/034.mp3", "text": "Write a short quotation (30–50 words) for a product: unit price, quantity, discount, total, currency, valid-until."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/part-11-foundations/035.mp3", "text": "Check your maths."}], "title": "Read and listen"}], "warm-up": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/001.mp3", "text": "Look at the pictures."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/002.mp3", "text": "Answer these questions before you read."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/003.mp3", "text": "Ms. Chen likes Al-Hasan's products."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/004.mp3", "text": "Now she wants to know the exact prices."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/005.mp3", "text": "So she asks for a QUOTATION."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/006.mp3", "text": "A quotation is a price offer."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/007.mp3", "text": "It says: this is our product, this is the price, this is the total."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/008.mp3", "text": "A good quotation is clear, correct, and fair."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/009.mp3", "text": "Lina, the Financial Manager, prepares the quotation."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/010.mp3", "text": "It is important work, because prices are serious."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/011.mp3", "text": "If the price is too high, the partner says no."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/012.mp3", "text": "If it is too low, the company makes no profit."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/013.mp3", "text": "Lina must find the right price — a fair price for both sides."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/014.mp3", "text": "She makes a table."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/015.mp3", "text": "“The cement is 50 dollars per tonne,” she says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/016.mp3", "text": "“Ms. Chen wants 1,000 tonnes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/017.mp3", "text": "So the total is 50,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/018.mp3", "text": "But for a big order, we can give a discount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/019.mp3", "text": "Let's give 10% off."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/020.mp3", "text": "So the price is 45 dollars per tonne, and the total is 45,000 dollars.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/021.mp3", "text": "Karim checks the numbers."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/022.mp3", "text": "“Good,” he says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/023.mp3", "text": "“The quotation is clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/024.mp3", "text": "And 45 dollars is a good price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/025.mp3", "text": "Our cement is cheaper than the cement from other companies, and it is higher quality."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/026.mp3", "text": "That is a strong offer.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/027.mp3", "text": "Lina adds one more thing."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/028.mp3", "text": "“We must say how long the price is good."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/029.mp3", "text": "Prices can change."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/030.mp3", "text": "Let's say the quotation is valid for 30 days.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/031.mp3", "text": "“Perfect,” says Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/032.mp3", "text": "“Now write the email.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/033.mp3", "text": "Lina writes: “Dear Ms. Chen, thank you for your interest."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/034.mp3", "text": "Please find our quotation below."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/035.mp3", "text": "Cement: 45 dollars per tonne (10% discount for a large order)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/036.mp3", "text": "For 1,000 tonnes, the total is 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/037.mp3", "text": "This price is valid for 30 days."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/038.mp3", "text": "Best regards, Lina.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/039.mp3", "text": "Ms. Chen reads the quotation."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/040.mp3", "text": "“This is very clear,” she thinks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/041.mp3", "text": "“A good price, a good discount, and high quality."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/042.mp3", "text": "Al-Hasan's cement is cheaper than the others, and better.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/043.mp3", "text": "She is happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-04/warm-up/044.mp3", "text": "The quotation is a strong step towards an order."}], "title": "Read and listen"}]}, "unit": 4});
